import{stateMissions}from"./js-modules/stateMissions.js";import{playerStore}from"./js-modules/playerStore.js";function initUI(){const t=playerStore.state;updateStatsUI(t),renderPassportBook(t),renderMissions(t),document.getElementById("close-modal").addEventListener("click",()=>{document.getElementById("reward-modal").classList.add("hidden")})}function updateStatsUI(t){document.getElementById("stat-xp").textContent=t.xp,document.getElementById("stat-coins").textContent=t.coins,document.getElementById("stat-stamps").textContent=`${t.stamps.length} / 28`}function renderPassportBook(t){const e=document.getElementById("stamp-grid");e.innerHTML="",stateMissions.forEach(n=>{const s=t.completedMissions.includes(n.id),o=document.createElement("div");o.className="stamp-slot "+(s?"collected":""),o.textContent=s?n.stamp.replace(/_/g," ").toUpperCase():"?",e.appendChild(o)});const n=document.getElementById("unlocked-list");n.innerHTML="",0===t.unlockedItems.length?n.innerHTML='<li><span style="color:var(--text-secondary)">No items unlocked yet.</span></li>':t.unlockedItems.forEach(t=>{const e=document.createElement("li");e.textContent=`🎁 ${t}`,n.appendChild(e)})}function renderMissions(t){const e=document.getElementById("missions-list");e.innerHTML="",stateMissions.forEach(n=>{const s=t.completedMissions.includes(n.id),o=document.createElement("div");if(o.className="mission-card "+(s?"completed":""),o.innerHTML=`\n            <div class="mission-info">\n                <h3>📍 ${n.state}</h3>\n                <p><strong>Mission:</strong> ${n.mission}</p>\n                <p>${n.description}</p>\n                <div class="mission-rewards">\n                    <span>⭐ ${n.xp} XP</span>\n                    <span>🪙 ${n.coins} Coins</span>\n                    <span>📖 Stamp</span>\n                </div>\n            </div>\n            <button class="btn-start" ${s?"disabled":""}>\n                ${s?"Completed":"Start Mission"}\n            </button>\n        `,!s){o.querySelector(".btn-start").addEventListener("click",()=>startMission(n))}e.appendChild(o)})}function startMission(t){setTimeout(()=>{const e=playerStore.completeMission(t);e.success&&showRewardPopup(e.mission,e.newUnlocks)},500)}function showRewardPopup(t,e){document.getElementById("popup-xp").textContent=`⭐ +${t.xp} XP`,document.getElementById("popup-coins").textContent=`🪙 +${t.coins} Coins`,document.getElementById("popup-stamp").textContent=`📖 ${t.state} Stamp Added`;const n=document.getElementById("popup-unlock-container"),s=document.getElementById("popup-unlock-item");e&&e.length>0?(n.classList.remove("hidden"),s.textContent=e.join(", ")):n.classList.add("hidden"),document.getElementById("reward-modal").classList.remove("hidden")}document.addEventListener("DOMContentLoaded",()=>{initUI(),playerStore.subscribe(t=>{updateStatsUI(t),renderPassportBook(t),renderMissions(t)})});